def longest_run(lst):
    if not lst:
        return 0
    best = 0
    cur = 1
    for i in range(1, len(lst)):
        if lst[i] == lst[i - 1]:
            cur += 1
        else:
            best = max(best, cur)
            cur = 1
    return max(best, cur)

